arguments.command:
cd /app && cat > /tmp/strict_notag_test.go <<'GOEOF'
package participle_test

import (
	"testing"

	"github.com/alecthomas/assert/v2"
	"github.com/alecthomas/participle/v2"
)

func TestStrictModeNoTagNoOp(t *testing.T) {
	type G struct {
		A string `@Ident | @Ident`
	}
	_, err := participle.Build[G](participle.StrictMode())
	assert.NoError(t, err)
}
GOEOF
cp /tmp/strict_notag_test.go ./zz_strict_notag_test.go
go test -run TestStrictModeNoTagNoOp -v . 2>&1 | head -10
rm -f ./zz_strict_notag_test.go
